BEGIN;
ALTER TABLE assessment.models ADD COLUMN form_schema jsonb NOT NULL DEFAULT '{}';
CREATE OR REPLACE FUNCTION assessment.model_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Scoring model history cannot be deleted'; END IF;
 IF OLD.state<>'DRAFT' AND (NEW.definition IS DISTINCT FROM OLD.definition OR NEW.form_schema IS DISTINCT FROM OLD.form_schema OR NEW.version<>OLD.version OR NEW.title<>OLD.title) THEN RAISE EXCEPTION 'Published model is immutable'; END IF;
 IF NOT (NEW.state=OLD.state OR (OLD.state='DRAFT' AND NEW.state='APPROVED') OR (OLD.state='APPROVED' AND NEW.state='ACTIVE') OR (OLD.state='ACTIVE' AND NEW.state='RETIRED')) THEN RAISE EXCEPTION 'Invalid model transition'; END IF; RETURN NEW; END $$;
