CREATE TABLE assessment.drafts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),family_id uuid NOT NULL REFERENCES family.families(id),model_id uuid NOT NULL REFERENCES assessment.models(id),created_by uuid NOT NULL REFERENCES identity.accounts(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version integer NOT NULL DEFAULT 1,payload jsonb NOT NULL DEFAULT '{}',submitted_snapshot_id uuid REFERENCES assessment.snapshots(id));
CREATE UNIQUE INDEX one_open_draft_per_family ON assessment.drafts(family_id) WHERE submitted_snapshot_id IS NULL;
CREATE TRIGGER draft_no_delete BEFORE DELETE ON assessment.drafts FOR EACH ROW EXECUTE FUNCTION guidance.no_delete();
CREATE FUNCTION assessment.draft_final_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.submitted_snapshot_id IS NOT NULL THEN RAISE EXCEPTION 'Submitted draft is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER draft_final_guard BEFORE UPDATE ON assessment.drafts FOR EACH ROW EXECUTE FUNCTION assessment.draft_final_guard();
CREATE TRIGGER document_immutable_update BEFORE UPDATE ON family.documents FOR EACH ROW EXECUTE FUNCTION guidance.immutable();
INSERT INTO guidance.history(entity_type,entity_id,action,new_state,reason) SELECT 'SCORING_MODEL',id,'MODEL_ACTIVE',jsonb_build_object('version',version),'ثبت مدل بر اساس جدول مصوب کاربر' FROM assessment.models WHERE version='1.0';
COMMIT;
